import React, { useEffect, useState } from 'react';

function FeedbackList({ reloadFlag }) {
  const [feedbacks, setFeedbacks] = useState([]);

  useEffect(() => {
    fetch('http://localhost:3001/api/feedback')
      .then(res => res.json())
      .then(data => setFeedbacks(data))
      .catch(err => console.error('Ошибка загрузки отзывов:', err));
  }, [reloadFlag]);

  return (
    <div className="mt-8 p-6 bg-white rounded-2xl shadow-xl max-w-2xl mx-auto">
      <h3 className="text-2xl font-semibold text-indigo-600 text-center mb-6">Отзывы пользователей</h3>
      {feedbacks.length === 0 ? (
        <p className="text-gray-500 text-center">Пока нет отзывов.</p>
      ) : (
        <div className="space-y-4">
          {feedbacks.map(fb => (
            <div
              key={fb.id}
              className="p-4 bg-gray-50 rounded-lg shadow-sm border border-gray-200 hover:bg-gray-100 transition-colors duration-200"
            >
              <p className="text-sm text-gray-600">
                <strong className="text-indigo-700">{fb.username}</strong> (
                {new Date(fb.submitted_at).toLocaleString('ru-RU', {
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric',
                  hour: '2-digit',
                  minute: '2-digit',
                })}):
              </p>
              <p className="mt-2 text-gray-800">{fb.comment}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default FeedbackList;
